using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Web.Script.Serialization;

public sealed class StorageTrashEntry {
 public string Id,DeviceId,Endpoint,Original,Held,Name,State="planned";public long Bytes;public DateTime Stamp,Created;public bool Restored;
}
public sealed partial class WorkbenchWindow {
 readonly object storageGate=new object();readonly Dictionary<string,StorageScanJob> storageScans=new Dictionary<string,StorageScanJob>();readonly Dictionary<string,StorageSnapshot> storageSnapshots=new Dictionary<string,StorageSnapshot>();readonly SemaphoreSlim storageQueries=new SemaphoreSlim(1,1),storageActions=new SemaphoreSlim(1,1);readonly List<Task> storageWrites=new List<Task>();bool storageClosing;
 string StorageFile(string deviceId){using(var sha=SHA256.Create()){string name=BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(deviceId))).Replace("-","");return Path.Combine(WorkbenchHost.DataRoot,"Storage",name+".json.gz");}}
 static string StorageEndpoint(Server server){return StorageSnapshot.EndpointFor(server);}
 void CacheStorageSnapshot(string deviceId,StorageSnapshot snapshot){lock(storageGate){storageSnapshots[deviceId]=snapshot;foreach(var old in storageSnapshots.Keys.Where(x=>x!=deviceId).Take(Math.Max(0,storageSnapshots.Count-3)).ToArray()){storageSnapshots.Remove(old);StorageScanJob job;if(storageScans.TryGetValue(old,out job)&&job.Work!=null&&job.Work.IsCompleted)storageScans.Remove(old);}}}
 async Task<object> StorageRequest(string method,Dictionary<string,object> p){
  if(method=="storage.jobs"){lock(storageGate)return storageScans.Values.Select(x=>x.View()).ToArray();}
  var server=devices.Find(FileText(p,"deviceId",devices.Selected)).Copy();string deviceId=PreviewDevices.Id(server);
  lock(storageGate)if(storageClosing)throw new IOException("存储任务正在退出");
  if(method=="storage.directories") {
   await fileReadSlots.WaitAsync(fileLifetime.Token);try{return await Task.Run(async()=>{using(var c=new FileConnection(server)){await c.Connect(fileLifetime.Token).ConfigureAwait(false);string path=FileText(p,"path");path=string.IsNullOrWhiteSpace(path)?c.Home:PreviewFileCopy.Normalize(server.IsLocal,path);PreviewFileCopy.SafePath(c,path);int offset;int.TryParse(FileText(p,"offset","0"),out offset);offset=Math.Max(0,Math.Min(100000,offset));var rows=c.Enumerate(path,fileLifetime.Token).Where(x=>x.IsDirectory&&!x.IsLink).Skip(offset).Take(201).ToArray();return (object)new{path=path,parent=FileTools.Parent(server.IsLocal,path),offset=offset,more=rows.Length>200,items=rows.Take(200).Select(x=>new{name=x.Name,path=x.FullPath}).ToArray()};}});}finally{fileReadSlots.Release();}
  }
  if(method=="storage.scan"){
   StorageScanJob job;lock(storageGate){StorageScanJob previous;if(storageScans.TryGetValue(deviceId,out previous)&&new[]{"queued","enumerating","paused","aggregating"}.Contains(previous.Status))throw new IOException("此设备已有扫描，可暂停或取消后重试");foreach(var obsolete in storageScans.Where(x=>x.Key!=deviceId&&x.Value.Work!=null&&x.Value.Work.IsCompleted).Select(x=>x.Key).Take(Math.Max(0,storageScans.Count-15)).ToArray()){storageScans.Remove(obsolete);storageSnapshots.Remove(obsolete);}if(storageScans.Values.Count(x=>new[]{"queued","enumerating","paused","aggregating"}.Contains(x.Status))>=2)throw new IOException("最多同时扫描两台设备，请等待或取消现有扫描");job=new StorageScanJob(server,FileText(p,"path"));storageScans[deviceId]=job;job.Work=Task.Run(async()=>{await job.Run();if(job.Status=="ready"){try{await storageQueries.WaitAsync(job.Cancel.Token);try{job.Cancel.Token.ThrowIfCancellationRequested();job.Result.Save(StorageFile(deviceId));CacheStorageSnapshot(deviceId,job.Result);}finally{storageQueries.Release();}}catch(OperationCanceledException){lock(job.Gate)job.Status="cancelled";}catch(Exception){lock(job.Gate){job.Status="failed";job.Error="无法保存扫描索引，已保留上次结果";}}}});}return job.View();
  }
  if(method=="storage.control"){StorageScanJob job;lock(storageGate){if(!storageScans.TryGetValue(deviceId,out job)||job.Result.Id!=FileText(p,"id"))throw new IOException("扫描任务已改变");}string action=FileText(p,"action");lock(job.Gate){if(action=="cancel"){job.Cancel.Cancel();job.Resume.Set();}else if(action=="pause"&&job.Status=="enumerating"){job.Resume.Reset();job.Status="paused";}else if(action=="resume"&&job.Status=="paused"){job.Status="enumerating";job.Resume.Set();}else throw new IOException("此任务当前无法执行该操作");}return job.View();}
  await storageQueries.WaitAsync(fileLifetime.Token);try{
   StorageSnapshot snapshot;lock(storageGate)storageSnapshots.TryGetValue(deviceId,out snapshot);
   if(snapshot==null){snapshot=await Task.Run(()=>StorageSnapshot.Load(StorageFile(deviceId)));if(snapshot!=null&&snapshot.DeviceId==deviceId)CacheStorageSnapshot(deviceId,snapshot);else snapshot=null;}
   if(snapshot!=null&&snapshot.Endpoint!=StorageEndpoint(server))snapshot=null;
   if(method=="storage.status"){StorageScanJob job;lock(storageGate)storageScans.TryGetValue(deviceId,out job);return new{deviceId=deviceId,job=job==null?null:job.View(),snapshot=snapshot==null?null:new{id=snapshot.Id,root=snapshot.Root,created=snapshot.Created.ToString("o"),partial=snapshot.Partial,skipped=snapshot.Skipped,bytes=snapshot.Node("0").Bytes,count=snapshot.Node("0").Count},isLocal=server.IsLocal};}
   if(method=="storage.trash.list")return await Task.Run(()=>ReadStorageTrash().Where(x=>x.DeviceId==deviceId&&x.Endpoint==StorageEndpoint(server)&&!x.Restored&&x.State!="failed"&&x.State!="deleted").Select(x=>new{id=x.Id,name=x.Name,path=x.Original,bytes=x.Bytes,created=x.Created.ToString("o"),state=x.State}).ToArray());
   if(method=="storage.trash.delete")return await StorageWrite(()=>DeleteStorageTrash(server,p));
   if(method=="storage.trash.restore")return await StorageWrite(()=>RestoreStorageTrash(server,FileText(p,"id")));
   if(snapshot==null)throw new IOException("请先扫描一个文件夹");if(snapshot.Id!=FileText(p,"snapshotId"))throw new IOException("扫描结果已更新，请重新选择项目");
   if(method=="storage.query")return await Task.Run(()=>QueryStorage(snapshot,p));
   // Writes revalidate the selected configured endpoint and scanned identities.
   StorageScanJob owner;lock(storageGate)storageScans.TryGetValue(deviceId,out owner);if(owner!=null&&!SameTerminalConfiguration(owner.Device,server))throw new IOException("设备连接已改变，请重新扫描");
   if(method=="storage.trash")return await StorageWrite(()=>TrashStorageFiles(server,snapshot,p));
   if(method=="storage.copy"){
    var ids=StorageIds(p);var selected=ids.Select(snapshot.Node).ToArray();var target=snapshot.Node(FileText(p,"targetId","0"));if(!target.Directory)throw new IOException("粘贴目标必须是文件夹");
    await Task.Run(async()=>{using(var connection=new FileConnection(server)){await connection.Connect(fileLifetime.Token).ConfigureAwait(false);foreach(var n in selected)ValidateStorageNode(connection,n);}});
    var args=new Dictionary<string,object>{{"sourceDeviceId",deviceId},{"targetDeviceId",deviceId},{"sourceSide",server.IsLocal?"local":"remote"},{"targetSide",server.IsLocal?"local":"remote"},{"targetPath",target.Path},{"paths",selected.Select(x=>x.Path).ToArray()},{"keepBoth",true}};
    return await FilesRequest("files.prepare",args);
   }
   throw new IOException("未知存储操作");
  }finally{storageQueries.Release();}
 }
 static string[] StorageIds(Dictionary<string,object> p){object value;if(!p.TryGetValue("ids",out value)||!(value is IEnumerable))throw new IOException("请选择文件");var ids=((IEnumerable)value).Cast<object>().Select(Convert.ToString).Distinct().ToArray();if(ids.Length==0||ids.Length>256)throw new IOException("每次请选择 1 至 256 项");return ids;}
 static object QueryStorage(StorageSnapshot s,Dictionary<string,object> p){string query=FileText(p,"query").Trim();bool large=FileText(p,"mode")=="large";int offset;int.TryParse(FileText(p,"offset","0"),out offset);offset=Math.Max(0,offset);long min;long.TryParse(FileText(p,"minBytes","0"),out min);string kind=FileText(p,"kind");int days;int.TryParse(FileText(p,"olderThanDays","0"),out days);days=Math.Max(0,Math.Min(36500,days));var before=DateTime.UtcNow.AddDays(-days);bool foldersOnly=FileText(p,"foldersOnly").Equals("true",StringComparison.OrdinalIgnoreCase);var node=s.Node(FileText(p,"nodeId","0"));IEnumerable<StorageNode> items=large?s.Largest.Select(s.Node):node.Children.Select(id=>s.Nodes[id]).Where(n=>!n.Removed);items=items.Where(n=>(!foldersOnly||n.Directory)&&(days==0||n.Stamp.ToUniversalTime()<before)&&n.Bytes>=min&&(query.Length==0||n.Name.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||large&&n.Path.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0)&&(kind.Length==0||StorageKind(n)==kind));int total=0;long bytes=0;var page=new List<StorageNode>(200);foreach(var n in items){if(total>=offset&&page.Count<200)page.Add(n);total++;bytes+=n.Bytes;}var crumbs=new List<object>();StorageNode cursor=node;while(cursor!=null){crumbs.Insert(0,cursor.View());cursor=cursor.Parent==null?null:s.Node(cursor.Parent);}return new{snapshotId=s.Id,node=node.View(),crumbs=crumbs.ToArray(),total=total,bytes=bytes,offset=offset,limit=200,items=page.Select(n=>new{id=n.Id,parent=n.Parent,name=n.Name,path=n.Path,directory=n.Directory,bytes=n.Bytes,modified=n.Stamp.ToString("o"),count=n.Count,kind=StorageKind(n),incomplete=n.Incomplete}).ToArray(),partial=s.Partial,skipped=s.Skipped};}
 static string StorageKind(StorageNode n){if(n.Directory)return "folder";string extension=Path.GetExtension(n.Name).ToLowerInvariant();if(new[]{".zip",".7z",".tar",".gz",".rar",".xz"}.Contains(extension))return "archive";if(new[]{".pt",".pth",".onnx",".safetensors",".ckpt",".bin"}.Contains(extension))return "model";if(new[]{".mp4",".mkv",".mov",".png",".jpg",".jpeg",".webp"}.Contains(extension))return "media";if(new[]{".db",".sqlite",".sqlite3",".mdb",".mdf",".log"}.Contains(extension))return "data";return "file";}
 static void ValidateStorageNode(FileConnection c,StorageNode n){PreviewFileCopy.SafePath(c,n.Path);if(!c.Exists(n.Path)||c.IsDirectory(n.Path)!=n.Directory)throw new IOException("项目已变化，请重新扫描："+n.Name);if(!n.Directory&&(c.Length(n.Path)!=n.Bytes||Math.Abs((c.Stamp(n.Path)-n.Stamp).TotalSeconds)>1))throw new IOException("文件已被修改，已保留："+n.Name);}
 string StorageTrashFile{get{return Path.Combine(WorkbenchHost.DataRoot,"Storage","recycle.json");}}
 List<StorageTrashEntry> ReadStorageTrash(){if(!File.Exists(StorageTrashFile))return new List<StorageTrashEntry>();return new JavaScriptSerializer{MaxJsonLength=16000000}.Deserialize<List<StorageTrashEntry>>(File.ReadAllText(StorageTrashFile));}
 void SaveStorageTrash(List<StorageTrashEntry> entries){Directory.CreateDirectory(Path.GetDirectoryName(StorageTrashFile));string temp=StorageTrashFile+".tmp";File.WriteAllText(temp,new JavaScriptSerializer{MaxJsonLength=16000000}.Serialize(entries));if(File.Exists(StorageTrashFile))File.Replace(temp,StorageTrashFile,null);else File.Move(temp,StorageTrashFile);}
 async Task<object> StorageWrite(Func<Task<object>> action){await storageActions.WaitAsync(fileLifetime.Token);try{var task=Task.Run(action);lock(storageGate){storageWrites.RemoveAll(x=>x.IsCompleted);storageWrites.Add(task);}return await task;}finally{storageActions.Release();}}
 async Task<object> TrashStorageFiles(Server server,StorageSnapshot snapshot,Dictionary<string,object> p){if(!p.ContainsKey("confirm")||!Convert.ToBoolean(p["confirm"]))throw new IOException("请先确认移入回收区");var selected=StorageIds(p).Select(snapshot.Node).ToArray();if(selected.Any(x=>x.Directory))throw new IOException("回收区首期只接收文件，请进入文件夹后选择文件");if(!server.IsLocal&&(!p.ContainsKey("confirmUnused")||!Convert.ToBoolean(p["confirmUnused"])))throw new IOException("远端无法确认文件是否被占用，请先确认文件未被使用");var manifest=ReadStorageTrash();if(manifest.Count(x=>!x.Restored)>=5000)throw new IOException("回收区记录已达上限，请先恢复已有项目");var moved=new List<object>();var failed=new List<object>();
  using(var c=new FileConnection(server)){await c.Connect(fileLifetime.Token).ConfigureAwait(false);foreach(var node in selected){fileLifetime.Token.ThrowIfCancellationRequested();StorageTrashEntry entry=null;try{ValidateStorageNode(c,node);ProtectStoragePath(server,node.Path);if(server.IsLocal)using(var handle=new FileStream(node.Path,FileMode.Open,FileAccess.Read,FileShare.None)){}else if(StorageKind(node)=="data")throw new IOException("数据库或日志文件可能正在使用，已保留");string parent=FileTools.Parent(server.IsLocal,node.Path),trash=FileTools.Join(server.IsLocal,parent,".asterhub-trash");if(c.Exists(trash)){PreviewFileCopy.SafePath(c,trash);if(!c.IsDirectory(trash))throw new IOException("回收区路径被占用");}else c.MakeDirectory(trash);string id=Guid.NewGuid().ToString("N"),folder=FileTools.Join(server.IsLocal,trash,id);c.MakeDirectory(folder);PreviewFileCopy.SafePath(c,folder);if(server.IsLocal)try{File.SetAttributes(trash,File.GetAttributes(trash)|FileAttributes.Hidden);}catch{}
    entry=new StorageTrashEntry{Id=id,DeviceId=snapshot.DeviceId,Endpoint=StorageEndpoint(server),Name=node.Name,Original=node.Path,Held=FileTools.Join(server.IsLocal,folder,node.Name),Bytes=node.Bytes,Stamp=node.Stamp,Created=DateTime.UtcNow};manifest.Add(entry);SaveStorageTrash(manifest);ValidateStorageNode(c,node);c.MoveRecoverable(node.Path,entry.Held);entry.State="moved";SaveStorageTrash(manifest);node.Removed=true;moved.Add(new{id=node.Id,name=node.Name,recycleId=entry.Id});
   }catch(Exception ex){if(entry!=null&&c.Exists(entry.Held)&&!c.Exists(entry.Original)){entry.State="moved";node.Removed=true;moved.Add(new{id=node.Id,name=node.Name,recycleId=entry.Id});}else{if(entry!=null)entry.State="failed";failed.Add(new{id=node.Id,name=node.Name,error=ex.GetBaseException().Message});}SaveStorageTrash(manifest);}}
  }snapshot.Aggregate();snapshot.Save(StorageFile(snapshot.DeviceId));return new{moved=moved.ToArray(),failed=failed.ToArray(),spaceFreed=false};
 }
 static void ProtectStoragePath(Server server,string path){string p=path.Replace('\\','/').ToLowerInvariant();if(server.IsLocal){var roots=new[]{Environment.GetFolderPath(Environment.SpecialFolder.Windows),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),AppDomain.CurrentDomain.BaseDirectory,WorkbenchHost.DataRoot};if(roots.Where(x=>!string.IsNullOrEmpty(x)).Any(x=>p.StartsWith(x.Replace('\\','/').TrimEnd('/').ToLowerInvariant()+"/",StringComparison.Ordinal)))throw new IOException("此路径受保护，不能在清理工具中移动");}else if(new[]{"/etc/","/usr/","/bin/","/sbin/","/boot/","/proc/","/sys/","/dev/","/run/","/var/lib/","/var/log/"}.Any(x=>p.StartsWith(x,StringComparison.Ordinal)))throw new IOException("系统或服务目录受保护");}
 async Task<object> RestoreStorageTrash(Server server,string id){var entries=ReadStorageTrash();var entry=entries.FirstOrDefault(x=>x.Id==id&&!x.Restored&&x.DeviceId==PreviewDevices.Id(server)&&x.Endpoint==StorageEndpoint(server));if(entry==null)throw new IOException("此恢复记录不存在或不属于当前设备");string parent=FileTools.Parent(server.IsLocal,entry.Original),expected=FileTools.Join(server.IsLocal,FileTools.Join(server.IsLocal,FileTools.Join(server.IsLocal,parent,".asterhub-trash"),entry.Id),entry.Name);if(entry.Name.IndexOfAny(new[]{'/','\\'})>=0||entry.Name=="."||entry.Name==".."||expected!=entry.Held||entry.Id.Length!=32||entry.Id.Any(x=>!Uri.IsHexDigit(x)))throw new IOException("恢复记录无效");using(var c=new FileConnection(server)){await c.Connect(fileLifetime.Token).ConfigureAwait(false);PreviewFileCopy.SafePath(c,entry.Held);PreviewFileCopy.SafePath(c,parent);if(c.Exists(entry.Original))throw new IOException("原路径已有同名文件，已保留回收区文件");if(!c.Exists(entry.Held)||c.IsDirectory(entry.Held)||c.Length(entry.Held)!=entry.Bytes||Math.Abs((c.Stamp(entry.Held)-entry.Stamp).TotalSeconds)>1)throw new IOException("回收区文件已变化，已保留，请手动检查");c.MoveRecoverable(entry.Held,entry.Original);entry.Restored=true;entry.State="restored";SaveStorageTrash(entries);}return new{restored=true,path=entry.Original};}
 async Task<object> DeleteStorageTrash(Server server,Dictionary<string,object> p){
  if(!FileText(p,"confirm").Equals("true",StringComparison.OrdinalIgnoreCase))throw new IOException("请确认永久删除");
  var entries=ReadStorageTrash();string id=FileText(p,"id");var entry=entries.FirstOrDefault(x=>x.Id==id&&!x.Restored&&x.State=="moved"&&x.DeviceId==PreviewDevices.Id(server)&&x.Endpoint==StorageEndpoint(server));
  if(entry==null)throw new IOException("回收记录不存在或不属于当前设备");
  string parent=FileTools.Parent(server.IsLocal,entry.Original),expected=FileTools.Join(server.IsLocal,FileTools.Join(server.IsLocal,FileTools.Join(server.IsLocal,parent,".asterhub-trash"),entry.Id),entry.Name);
  if(entry.Name.IndexOfAny(new[]{'/','\\'})>=0||entry.Name=="."||entry.Name==".."||expected!=entry.Held||entry.Id.Length!=32||entry.Id.Any(x=>!Uri.IsHexDigit(x)))throw new IOException("回收记录无效");
  using(var c=new FileConnection(server)){await c.Connect(fileLifetime.Token).ConfigureAwait(false);PreviewFileCopy.SafePath(c,entry.Held);
   if(!c.Exists(entry.Held)||c.IsDirectory(entry.Held)||c.Length(entry.Held)!=entry.Bytes||Math.Abs((c.Stamp(entry.Held)-entry.Stamp).TotalSeconds)>1)throw new IOException("回收区文件已变化，已保留，请手动检查");
   c.RemoveOwnPart(entry.Held);entry.State="deleted";SaveStorageTrash(entries);
  }
  return new{deleted=true,bytes=entry.Bytes};
 }
 async Task CleanupStorage(){Task[] writes,scans;lock(storageGate){storageClosing=true;foreach(var job in storageScans.Values){job.Cancel.Cancel();job.Resume.Set();}writes=storageWrites.ToArray();scans=storageScans.Values.Where(x=>x.Work!=null).Select(x=>x.Work).ToArray();}await Task.WhenAll(writes);await Task.WhenAny(Task.WhenAll(scans),Task.Delay(3000));}
}
